// Package pstack sets up and launches the pstack evaluation profile
// (rules/decisions/2026-10-17-pstack-evaluation-profile.md): a second Claude
// Code configuration directory, generated by jig under the `pstack` rules
// profile, in which the pstack plugin is loaded for one session at a time
// from a checkout pinned to one upstream commit. Nothing from upstream is
// copied into the dotfiles; the pin lives in harness/profiles/pstack/upstream.json.
package pstack

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/esh2n/dotfiles/pkgs/dotctl/internal/ui"
)

// System is the part of the machine this package drives (sys.OS in production).
type System interface {
	Run(env []string, name string, args ...string) error
	Output(name string, args ...string) (string, error)
	Has(name string) bool
}

// Env is where the profile lives and how it talks to the machine.
type Env struct {
	Home string
	Repo string // the dotfiles checkout
	Sys  System
	UI   ui.Printer
	// DataDir holds the upstream checkout; empty means $XDG_DATA_HOME/dotctl/pstack
	// (or ~/.local/share/dotctl/pstack).
	DataDir string
}

// ProfileName is the rules profile and the suffix of the configuration directory.
const ProfileName = "pstack"

// Upstream is harness/profiles/pstack/upstream.json.
type Upstream struct {
	Repo      string `json:"repo"`
	Commit    string `json:"commit"`
	Version   string `json:"version"`
	PluginDir string `json:"pluginDir"`
	Fixes     []Fix  `json:"fixes"`
}

// Fix is one line the pinned checkout needs before Claude Code can load it.
type Fix struct {
	File string `json:"file"`
	From string `json:"from"`
	To   string `json:"to"`
	Why  string `json:"why"`
}

var (
	commitRe = regexp.MustCompile(`^[0-9a-f]{40}$`)
	// a GitHub repository URL and nothing else: no userinfo, no path below the
	// repository, no other host — the pin names where the code comes from
	repoRe = regexp.MustCompile(`^https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$`)
)

// UpstreamPath is where the pin is read from.
func UpstreamPath(repo string) string {
	return filepath.Join(repo, "harness", "profiles", ProfileName, "upstream.json")
}

// LoadUpstream reads and checks the pin.
func LoadUpstream(repo string) (Upstream, error) {
	b, err := os.ReadFile(UpstreamPath(repo))
	if err != nil {
		return Upstream{}, fmt.Errorf("read the pstack pin: %w", err)
	}
	var u Upstream
	if err := json.Unmarshal(b, &u); err != nil {
		return Upstream{}, fmt.Errorf("the pstack pin is not JSON: %w", err)
	}
	switch {
	case !repoRe.MatchString(u.Repo):
		return Upstream{}, errors.New("the pstack pin's repo must be https://github.com/<owner>/<repo>, nothing more")
	case !commitRe.MatchString(u.Commit):
		return Upstream{}, errors.New("the pstack pin's commit must be a full 40-hex SHA")
	case u.PluginDir == "" || strings.HasPrefix(u.PluginDir, "/") || strings.Contains(u.PluginDir, ".."):
		return Upstream{}, errors.New("the pstack pin's pluginDir must be a relative path inside the checkout")
	}
	for _, f := range u.Fixes {
		if f.File == "" || f.From == "" || f.To == "" || strings.Contains(f.File, "..") {
			return Upstream{}, errors.New("every pstack fix needs file, from and to, inside the plugin")
		}
	}
	return u, nil
}

// ConfigDir is the Claude Code configuration directory of the profile.
func (e Env) ConfigDir() string { return filepath.Join(e.Home, ".claude-"+ProfileName) }

// CheckoutDir is where the pinned upstream repository is kept.
func (e Env) CheckoutDir() string {
	data := e.DataDir
	if data == "" {
		if xdg := os.Getenv("XDG_DATA_HOME"); xdg != "" {
			data = filepath.Join(xdg, "dotctl", ProfileName)
		} else {
			data = filepath.Join(e.Home, ".local", "share", "dotctl", ProfileName)
		}
	}
	return filepath.Join(data, "cursor-plugins")
}

// PluginDir is the directory `claude --plugin-dir` loads.
func (e Env) PluginDir(u Upstream) string {
	return filepath.Join(e.CheckoutDir(), filepath.FromSlash(u.PluginDir))
}

// ProfileEnv is the environment both jig and Claude Code run under for this
// profile: the configuration directory and the rules profile, as "K=v" entries.
func (e Env) ProfileEnv() []string {
	return []string{"CLAUDE_CONFIG_DIR=" + e.ConfigDir(), "JIG_PROFILE=" + ProfileName}
}
